-- Passage rg11-theme-summary-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('5014dedd-4788-5a9b-815f-3c11a732119c', 'rg11-theme-summary-p02', (select id from public.skills where slug = 'read-g11-theme-summary'), null,
        '9-12', $q$Stakes at the Edge of the Ice$q$, $q$Each August my aunt drives a stake of painted pine
into the gravel where the glacier ended last year,
and each August we hike a little farther uphill
to find where the ice has moved its edge.
The stakes stand behind us like a row of patient questions.

She writes the distance in a yellow notebook:
a number, a date, the color of the sky.
I asked her once why she kept counting something
she could not stop, and she handed me the tape.
Hold your end steady, she said. That is the whole job.

So I held it, while meltwater talked under the stones
in a voice older than any language we have,
and I learned the ice is not silent when it leaves.
It drips. It ticks. It shifts its weight like someone
standing up slowly from a long conversation.

This year the gap between the last two stakes
is wider than my arms can reach.
My aunt does not say anything about it.
She photographs the stake, the stones, my hands,
and writes the number down in careful ink.

I used to think a record was a way of holding on.
Now I think it is a way of paying attention,
of saying to something that is going,
I was here, and I saw you, and I wrote you down.
Next August I will carry the stakes myself.$q$, 'draft')
