  ('0355020a-0d13-525f-bc21-65f2faa6aeff', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'easy',
   $q$Which statement best expresses a central theme of the passage?$q$, $q$[{"text":"Scanning documents is a slow and repetitive job for a summer volunteer.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Old factories were dangerous places that should never have been built.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Archivists should never change a plan once they have written it down.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The experiences of ordinary workers deserve a place in how history is remembered.","is_correct":true}]$q$::jsonb, $q$The experiences of ordinary workers deserve a place in how history is remembered.$q$, $q$Dae-jung argues that only E.M.'s notes show "what it was like to work there," and the archive changes its list and catalog to include her. The passage never judges whether the mill should have been built.$q$, 'draft', 'd3f6bc26-2ac5-5558-9e14-0c71661a3691')
