  ('0c963e56-e5cd-5150-b5be-8589a650087a', null, (select id from public.skills where slug = 'read-g11-theme-summary'), null, 'medium',
   $q$How does the contrast between the owners' letters and the margin notes develop the theme?$q$, $q$[{"text":"It shows that the owners wrote more clearly than the workers did.","is_correct":false,"misconception_token":"literal-reading"},{"text":"It explains why researchers prefer contracts to personal writing.","is_correct":false,"misconception_token":"misidentifies-theme"},{"text":"The forgettable official letters make the vivid notes about rain, song, and a frightened new worker stand out as the human story.","is_correct":true},{"text":"It proves that the owners were dishonest about the mill's finances.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The forgettable official letters make the vivid notes about rain, song, and a frightened new worker stand out as the human story.$q$, $q$Dae-jung forgets each owner's letter, but he reads all of E.M.'s notes before lunch, which highlights what the official record leaves out. Nothing in the text suggests the owners were dishonest.$q$, 'draft', 'd3f6bc26-2ac5-5558-9e14-0c71661a3691')
